class t{archiveBaseUrl="/events-archive";async createArchiveFile(r){try{const e=await fetch("/api/create-archive",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(r)});if(!e.ok)throw new Error(`Error al crear archivo: ${e.statusText}`);const a=await e.json();return console.log(`✅ Archivo creado: ${a.fileName} con ${r.events.length} eventos`),{success:!0,fileName:a.fileName}}catch(e){return console.error("Error al crear archivo de archivo:",e),{success:!1,fileName:"",error:e instanceof Error?e.message:"Error desconocido"}}}async archiveExists(r){try{return(await fetch(`${this.archiveBaseUrl}/${r}.json`)).ok}catch{return!1}}async getArchiveData(r){try{const e=await fetch(`${this.archiveBaseUrl}/${r}.json`);return e.ok?await e.json():null}catch(e){return console.error(`Error al cargar archivo del año ${r}:`,e),null}}async getAvailableYears(){try{const r=await fetch(`${this.archiveBaseUrl}/index.json`);if(r.ok)return(await r.json()).years||[];const e=new Date().getFullYear(),a=[];for(let s=2020;s<e;s++)await this.archiveExists(s)&&a.push(s);return a}catch(r){return console.error("Error al obtener años disponibles:",r),[]}}}const c=new t;export{c as staticFileService};
